import json
from pathlib import Path
p=Path('PCB');d=json.loads((p/'manifests/routing-interface-v11.json').read_text(encoding='utf-8-sig'))['result'];sel={k:[t['id'] for t in d[k] if t['net']=='Q2_BASE'] for k in ['lines','polys','vias']};code='if((await eda.dmt_SelectControl.getCurrentDocumentInfo())?.uuid!=="4211128ecf040c100b33238447713203")throw Error("Wrong PCB");const specs='+json.dumps(sel)+';for(const [k,a] of [["lines",eda.pcb_PrimitiveLine],["polys",eda.pcb_PrimitivePolyline],["vias",eda.pcb_PrimitiveVia]])if(specs[k].length&&!await a.delete(specs[k]))throw Error("Reroute failed");const r=(await eda.pcb_PrimitiveComponent.getAll()).find(c=>c.getState_Designator()==="R30");if(!await eda.pcb_PrimitiveComponent.modify(r,{x:10.2/.0254,y:7.1/.0254,rotation:270}))throw Error("R30 relocation failed");return {specs,saved:await eda.pcb_Document.save()};';(p/'scripts/open-led-and-port-routing-v11.js').write_text(code)
